mapper.select:
SELECT p.id group_price_id, p.version, p.group_id, g.group_code, g.group_name, p.spu_id, sp.name product_name, p.sale_unit, p.unit_price, p.effective_from, p.effective_to, p.updated_at FROM xsy_customer_group_price p LEFT JOIN xsy_customer_group g ON g.id = p.group_id LEFT JOIN xsy_product_spu sp ON sp.id = p.spu_id WHERE p.deleted = FALSE AND p.group_id = #{query.groupId} AND p.spu_id = #{query.spuId}
AND (g.group_code ILIKE CONCAT('%', #{query.keyword}, '%') OR g.group_name ILIKE CONCAT('%', #{query.keyword}, '%') OR sp.name ILIKE CONCAT('%', #{query.keyword}, '%'))
AND (p.effective_to IS NULL OR p.effective_to > #{query.effectiveFrom})
AND p.effective_from < #{query.effectiveTo}

SELECT count(*)
FROM xsy_customer_group_price
WHERE group_id = #{groupId}
    AND spu_id = #{spuId}
    AND sale_unit = #{saleUnit}
    AND deleted = FALSE
    AND effective_from < COALESCE(#{to,jdbcType=TIMESTAMP_WITH_TIMEZONE}, 'infinity'::timestamptz)
    AND (effective_to IS NULL OR effective_to > #{from,jdbcType=TIMESTAMP_WITH_TIMEZONE})
AND id != #{excludeId}

mapper.update:
UPDATE xsy_customer_group_price
SET deleted = TRUE, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id}
    AND version = #{version}
    AND deleted = FALSE
